	[7045] = {
		id = 7045,
		key = 'reunionGiftText',
		text = '#C0x57472E#Xin chào! Lâu rồi không gặp~Tính ra bạn đã không đến thế giới này %s ngày rồi, đội Ninja của bạn bị mắc kẹt trong Tsukuyomi Vĩnh Hằng mãi, thiếu bạn—người dẫn đường thông thái—nên tất cả Ninja đều buồn bã…nhưng may quá bạn đã quay lại rồi, tất cả Ninja nhất định sẽ vui mừng vì được tụ họp cùng bạn lần nữa, kề vai sát cánh chiến đấu!\nTrong thời gian bạn rời đi, thế giới của chúng ta cũng thay đổi rất nhanh. Chúng tôi thêm hệ thống mới thú vị, cải thiện nhiều vấn đề ảnh hưởng lớn đến trải nghiệm, và còn phát hiện ra những Ninja mạnh hơn nữa……Lần này hy vọng thế giới này sẽ mang lại nhiều niềm vui hơn cho thời gian rảnh của bạn. Đã quay lại rồi thì ở lại luôn nhé!\nĐây là nội dung phần thưởng được “đo ni đóng giày” cho bạn, có nó bạn sẽ chơi dễ hơn, mau nhận đi!'
	},
